/**
 * Free-text entry of several values, shown as chips (`design/components/tag-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tag-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  cell,
  composingKey,
  derived,
  elementRef,
  fieldValue,
  holdFieldEscape,
  lineStartKey,
  mountEffect,
  presence,
  setup,
  uniqueId,
  useMember,
  watchEffect,
  type Each,
  type Emitted,
} from '@polymorph/angular'
import { useListPresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/controls/tag-input.module.css'
import { TagInputChip, type TagInputChipProps } from './TagInputChip'

/** Free-text entry of several values, shown as chips: the inputs it takes, by the React member's prop names. */
export interface TagInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * At the maximum the field is read-only, not removed and not disabled. A full field is still
   * what FormField's label points at, and keyboard users can still reach it. It blocks typing,
   * not access.
   */
  max?: number
  /**
   * Serialises comma-joined into a hidden input, for a native form post.
   */
  name?: string
  /**
   * Shown only while empty. The chips are the value, and a placeholder beside them is clutter.
   */
  placeholder?: string
  /**
   * The accessible name of a chip's remove button. It is a function because the tag is data and
   * the text around it comes from the app's message catalog. Defaults to `Remove {tag}`.
   */
  removeLabel?: (tag: string) => string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalize or reject: return the tag as it should be stored, or `null` to reject it. A
   * rejection flashes the container and shows no message. Persistent written errors come from
   * FormField.
   */
  validate?: (raw: string) => string | null
  value?: string[]
}

/** Free-text entry of several values, shown as chips. */
@Component({
  selector: 'pm-tag-input',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, TagInputChip],
  // prettier-ignore
  template: `<!-- container -->
<div
[attr.class]="e1()"
[attr.data-size]="e2()"
[attr.data-state]="e3()"
[attr.data-disabled]="e4()"
[attr.data-invalid]="e5()"
[attr.data-refused]="e6()"
data-member="tag-input"
(mousedown)="h1($event)"
(focusout)="h2($event)"
(animationend)="h3()"
><!-- chips -->
<ul
[attr.class]="e7()"
[pmRef]="chipList"
>@for (chip of e8(); track e9(chip)) {<li
pmTagInputChip
[tag]="e10(chip)"
[open]="e11(chip)"
[appear]="e12()"
[flash]="e13(chip)"
[disabled]="e14()"
[removeLabel]="e15(chip)"
(remove)="h4(chip)"
(keyDown)="h5($event, chip)"
(done)="h6(chip)"
></li>}</ul>
<!-- field -->
<input
[attr.class]="e16()"
type="text"
[value]="e17()"
[attr.placeholder]="e18()"
[attr.readonly]="e19()"
[attr.disabled]="e20()"
[attr.id]="e21()"
[attr.aria-label]="e22()"
[attr.aria-labelledby]="e23()"
[attr.aria-describedby]="e24()"
[attr.aria-required]="e25()"
[attr.aria-invalid]="e26()"
(input)="h7($event)"
(keydown)="h8($event)"
(paste)="h9($event)"
[pmRef]="field"
/>
<!-- count -->
<span
[attr.class]="e27()"
[attr.id]="e28()"
>{{ e29() }}</span>
<!-- announcer -->
<span
[attr.class]="e27()"
aria-live="polite"
>{{ e30() }}</span>
@if (e31()) {<input
type="hidden"
[attr.name]="e32()"
[value]="e33()"
[attr.disabled]="e34()"
/>}</div>`,
})
export class TagInput {
  static readonly controlKind = 'field'
  readonly ariaDescribedby = input<TagInputProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  readonly ariaLabel = input<TagInputProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<TagInputProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly ariaRequired = input<TagInputProps['aria-required']>(undefined, {
    alias: 'aria-required',
  })
  readonly defaultValue = input<TagInputProps['defaultValue']>(undefined)
  readonly disabled = input<
    Exclude<TagInputProps['disabled'], undefined>,
    TagInputProps['disabled']
  >(false, {
    transform: (value: TagInputProps['disabled']) => (value === undefined ? false : value),
  })
  readonly id = input<TagInputProps['id']>(undefined)
  readonly invalid = input<Exclude<TagInputProps['invalid'], undefined>, TagInputProps['invalid']>(
    false,
    { transform: (value: TagInputProps['invalid']) => (value === undefined ? false : value) },
  )
  /**
   * At the maximum the field is read-only, not removed and not disabled. A full field is still
   * what FormField's label points at, and keyboard users can still reach it. It blocks typing,
   * not access.
   */
  readonly max = input<TagInputProps['max']>(undefined)
  /**
   * Serialises comma-joined into a hidden input, for a native form post.
   */
  readonly name = input<TagInputProps['name']>(undefined)
  /**
   * Shown only while empty. The chips are the value, and a placeholder beside them is clutter.
   */
  readonly placeholder = input<TagInputProps['placeholder']>(undefined)
  /**
   * The accessible name of a chip's remove button. It is a function because the tag is data and
   * the text around it comes from the app's message catalog. Defaults to `Remove {tag}`.
   */
  readonly removeLabel = input<
    Exclude<TagInputProps['removeLabel'], undefined>,
    TagInputProps['removeLabel']
  >((tag: string) => `Remove ${tag}`, {
    transform: (value: TagInputProps['removeLabel']) =>
      value === undefined ? (tag: string) => `Remove ${tag}` : value,
  })
  readonly size = input<Exclude<TagInputProps['size'], undefined>, TagInputProps['size']>('md', {
    transform: (value: TagInputProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * Normalize or reject: return the tag as it should be stored, or `null` to reject it. A
   * rejection flashes the container and shows no message. Persistent written errors come from
   * FormField.
   */
  readonly validate = input<
    Exclude<TagInputProps['validate'], undefined>,
    TagInputProps['validate']
  >((raw: string) => (raw.trim() === '' ? null : raw.trim()), {
    transform: (value: TagInputProps['validate']) =>
      value === undefined ? (raw: string) => (raw.trim() === '' ? null : raw.trim()) : value,
  })
  readonly value = input<TagInputProps['value']>(undefined)
  /**
   * Fires when focus leaves the whole field, for touched validation. Chips and input are one
   * control, so moving focus between them is not a blur. Only leaving the field is.
   */
  readonly onBlur = output<FocusEvent>({ alias: 'blur' })
  readonly onChange = output<string[]>({ alias: 'change' })
  protected readonly $ = useMember({
    kind: TagInput.controlKind,
    events: ['blur', 'change'],
    props: {
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      'aria-required': () => this.ariaRequired(),
      defaultValue: () => this.defaultValue(),
      disabled: () => this.disabled(),
      id: () => this.id(),
      invalid: () => this.invalid(),
      max: () => this.max(),
      name: () => this.name(),
      placeholder: () => this.placeholder(),
      removeLabel: () => this.removeLabel(),
      size: () => this.size(),
      validate: () => this.validate(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly uncontrolled = cell(() => this.$p.defaultValue ?? [])
  protected readonly draft = cell(() => '')
  protected readonly flashing = cell(() => null as string | null)
  protected readonly refused = cell(() => false)
  protected readonly announcement = cell(() => '')
  protected readonly settled = cell(() => false)
  protected readonly chipList = elementRef<HTMLElement>()
  protected readonly field = elementRef<HTMLElement>()
  protected readonly values = derived(() => this.$p.value ?? this.uncontrolled.value)
  protected readonly atMax = derived(
    () => this.$p.max !== undefined && this.values.value.length >= this.$p.max,
  )
  protected readonly countId = derived(() => `${this.$p.id ?? this.uid}-count`)
  protected readonly commit = derived(() => (next: string[]) => {
    this.uncontrolled.value = next
    this.$.emit(this.onChange, 'onChange', next)
  })
  protected readonly add = derived(() => (raws: string[]) => {
    const next = [...this.values.value]
    let refusal = false
    let duplicate: string | null = null
    for (const raw of raws) {
      if (this.$p.max !== undefined && next.length >= this.$p.max) break
      const tag = this.$p.validate(raw)
      if (tag === null) {
        refusal = true
        continue
      }
      if (next.includes(tag)) {
        duplicate = tag
        continue
      }
      next.push(tag)
    }
    this.refused.value = refusal
    this.flashing.value = duplicate
    if (next.length !== this.values.value.length) this.commit.value(next)
  })
  protected readonly removeButton = derived(
    () => (at: number) =>
      this.chipList.value?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[
        at
      ] ?? null,
  )
  protected readonly remove = derived(() => (tag: string) => {
    const before = this.values.value
    const at = before.indexOf(tag)
    const target = at === -1 || at + 1 >= before.length ? null : this.removeButton.value(at + 1)
    this.commit.value(before.filter((other) => other !== tag))
    this.announcement.value = `${tag} removed, ${before.length - 1} remain`
    if (target) target.focus()
    else this.field.value?.focus()
  })
  protected readonly receive = derived(() => (event: Event) => {
    this.draft.value = (event.target as HTMLInputElement).value
  })
  protected readonly clearable = derived(() => this.draft.value !== '')
  protected readonly fieldKeyDown = derived(() => (event: KeyboardEvent) => {
    if (composingKey(event)) return
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault()
      this.add.value([this.draft.value])
      this.draft.value = ''
      return
    }
    if (event.key === 'Escape' && this.draft.value !== '') {
      event.preventDefault()
      this.draft.value = ''
      return
    }
    if (event.key === 'Backspace' && this.draft.value === '') {
      const last = this.values.value[this.values.value.length - 1]
      if (last !== undefined) this.remove.value(last)
      return
    }
    const input = event.target as HTMLInputElement
    if (event.key === lineStartKey(this.chipList.value ?? input) && input.selectionStart === 0) {
      this.removeButton.value(this.values.value.length - 1)?.focus()
    }
  })
  protected readonly chipKeyDown = derived(() => (event: KeyboardEvent, tag: string) => {
    const at = this.values.value.indexOf(tag)
    if (at === -1) return
    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault()
      this.remove.value(tag)
      return
    }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault()
      const step =
        event.key === lineStartKey(this.chipList.value ?? (event.target as Element)) ? -1 : 1
      if (at + step === this.values.value.length) this.field.value?.focus()
      else if (at + step >= 0) this.removeButton.value(at + step)?.focus()
    }
  })
  protected readonly receivePaste = derived(() => (event: ClipboardEvent) => {
    const pasted = event.clipboardData?.getData('text') ?? ''
    if (!/[\n,]+/.test(pasted)) return
    event.preventDefault()
    this.add.value(pasted.split(/[\n,]+/))
    this.draft.value = ''
  })
  protected readonly pressContainer = derived(() => (event: MouseEvent) => {
    if ((event.target as HTMLElement).closest('button, input')) return
    event.preventDefault()
    this.field.value?.focus()
  })
  protected readonly leave = derived(() => (event: FocusEvent) => {
    if ((event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) return
    this.$.emit(this.onBlur, 'onBlur', event)
  })
  protected readonly chips = setup(() =>
    useListPresence(
      () => this.values.value,
      (tag: string) => tag,
    ),
  )
  private release2: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    mountEffect(() => this.effect1())
    inject(DestroyRef).onDestroy(() => this.release2?.())
    watchEffect(
      () => this.clearable.value,
      () => this.effect2(),
      true,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return styles.container
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return this.atMax.value ? 'at-max' : undefined
  }

  protected e4() {
    return this.$p.disabled ? '' : undefined
  }

  protected e5() {
    return this.$p.invalid ? '' : undefined
  }

  protected e6() {
    return this.refused.value ? '' : undefined
  }

  protected h1($event: MouseEvent): void {
    this.pressContainer.value($event)
  }

  protected h2($event: FocusEvent): void {
    this.leave.value($event)
  }

  protected h3(): void {
    void ((this.refused.value = false), (this.flashing.value = null))
  }

  protected e7() {
    return styles.chips
  }

  e8() {
    return this.chips.value()
  }

  protected e9(chip: Each<ReturnType<TagInput['e8']>>) {
    return chip.key
  }

  protected e10(chip: Each<ReturnType<TagInput['e8']>>): TagInputChipProps['tag'] {
    return chip.item
  }

  protected e11(chip: Each<ReturnType<TagInput['e8']>>): TagInputChipProps['open'] {
    return chip.open
  }

  protected e12(): TagInputChipProps['appear'] {
    return this.settled.value
  }

  protected e13(chip: Each<ReturnType<TagInput['e8']>>): TagInputChipProps['flash'] {
    return this.flashing.value === chip.item
  }

  protected e14(): TagInputChipProps['disabled'] {
    return this.$p.disabled
  }

  protected e15(chip: Each<ReturnType<TagInput['e8']>>): TagInputChipProps['removeLabel'] {
    return this.$p.removeLabel(chip.item)
  }

  protected h4(chip: Each<ReturnType<TagInput['e8']>>): void {
    this.remove.value(chip.item)
  }

  protected h5(
    $event: Emitted<TagInputChip['onKeyDown']>,
    chip: Each<ReturnType<TagInput['e8']>>,
  ): void {
    this.chipKeyDown.value($event, chip.item)
  }

  protected h6(chip: Each<ReturnType<TagInput['e8']>>): void {
    chip.done()
  }

  protected e16() {
    return styles.input
  }

  protected e17() {
    return fieldValue(this.draft.value)
  }

  protected e18() {
    return this.values.value.length === 0 ? this.$p.placeholder : undefined
  }

  protected e19() {
    return presence(this.atMax.value)
  }

  protected e20() {
    return presence(this.$p.disabled)
  }

  protected e21() {
    return this.$p.id
  }

  protected e22() {
    return this.$p['aria-label']
  }

  protected e23() {
    return this.$p['aria-labelledby']
  }

  protected e24() {
    return [this.$p['aria-describedby'], this.countId.value].filter(Boolean).join(' ')
  }

  protected e25() {
    return this.$p['aria-required']
  }

  protected e26() {
    return this.$p.invalid ? true : undefined
  }

  protected h7($event: Event): void {
    this.receive.value($event)
  }

  protected h8($event: KeyboardEvent): void {
    this.fieldKeyDown.value($event)
  }

  protected h9($event: ClipboardEvent): void {
    this.receivePaste.value($event)
  }

  protected e27() {
    return styles.reader
  }

  protected e28() {
    return this.countId.value
  }

  protected e29() {
    return this.atMax.value
      ? `Maximum of ${this.$p.max} added`
      : `${this.values.value.length} added`
  }

  protected e30() {
    return this.announcement.value
  }

  protected e31() {
    return this.$p.name !== undefined
  }

  protected e32() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return this.$p.name
  }

  protected e33() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return fieldValue(this.values.value.join(','))
  }

  protected e34() {
    if (!(this.$p.name !== undefined)) return undefined as never
    return presence(this.$p.disabled)
  }

  private effect1(): void {
    this.settled.value = true
  }

  private effect2(): void {
    this.release2?.()
    const ran =
      this.clearable.value && this.field.value ? holdFieldEscape(this.field.value) : () => {}
    this.release2 = () => {
      ran()
    }
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'TagInput',
      element: () => this.field.value,
      state: () => ({
        value: this.values.value,
        disabled: this.$p.disabled,
        invalid: this.$p.invalid,
      }),
      actions: {
        add: {
          argument: 'text',
          run: (value) =>
            (() => {
              if (/[\n,]/.test(value)) {
                throw new Error('A tag holds no comma or line break: add each tag on its own.')
              }
              if (this.atMax.value)
                throw new Error(`The field holds its maximum of ${this.$p.max} tags.`)
              const tag = this.$p.validate(value)
              if (tag === null) throw new Error(`The field refuses "${value}" as a tag.`)
              if (this.values.value.includes(tag))
                throw new Error(`The field already holds "${tag}".`)
              this.add.value([value])
            })(),
        },
        clear: () =>
          (() => {
            if (this.values.value.length > 0) this.commit.value([])
          })(),
      },
    })
    this.release3 = () => {
      ran()
    }
  }
}
